1	function result = task005_evaluate(source_root, fixture_path)
2	% Run the public edited-MRS loading experiment against the current source tree.
3	
4	case_data = task005_load_case(fixture_path);
5	[ppm, spectra] = task005_build_spectra(case_data);
6	input_observation = task005_observe_spectra(ppm, spectra, case_data);
7	loaded_workflow = task005_run_loaded_workflow(source_root, ppm, spectra, case_data);
8	
9	result.case_name = case_data.name;
10	result.num_subspectra = columns(spectra);
11	result.input_observation = input_observation;
12	result.loaded_workflow = loaded_workflow;
13	result.workflow_completed = loaded_workflow.workflow_completed;
14	end
