148	function ok = task005_valid_loaded_struct(value, expected_subspecs)
149	ok = isstruct(value) && isfield(value, 'fids') && isfield(value, 'specs') && ...
150	    isfield(value, 'dims') && isfield(value, 'subspecs') && value.subspecs == expected_subspecs && ...
151	    all(isfinite(value.fids(:))) && all(isfinite(value.specs(:)));
152	end
153	
154	function spectra = task005_average_loaded_spectra(loaded)
155	spectra = loaded.specs;
156	if isfield(loaded.dims, 'averages') && loaded.dims.averages > 0
157	    spectra = mean(spectra, loaded.dims.averages);
158	end
159	spectra = squeeze(spectra);
160	if isvector(spectra)
161	    spectra = spectra(:);
162	end
163	end
