134	end
135	    if ~MRSCont.flags.isSERIES
136	        if length(MRSCont.opts.ECC.raw) == 1
137	            MRSCont.opts.ECC.raw = ones(size(MRSCont.files)) * MRSCont.opts.ECC.raw;
138	        else
139	            MRSCont.opts.ECC.raw = repmat(MRSCont.opts.ECC.raw, [ MRSCont.nDatasets(2) 1]);
140	        end  
