549	%                     % with the negative phase of that fit
550	                    [raw,ph]       = op_phaseCrCho(raw, 1);
551	
552	                else
553	                    refShift_SubSpecAlign =0;
554	                end
555	
556	                switch MRSCont.opts.SubSpecAlignment.mets
557	                    case 'L1Norm'
558	                        [raw]  = osp_editSubSpecAlignLNorm(raw,seq);
559	                    case 'L2Norm'
560	                        [raw]  = osp_editSubSpecAlign(raw, seq, target,MRSCont.opts.UnstableWater);
561	                    otherwise
562	                end
563	
564	                if MRSCont.flags.hasMM
565	                    raw_mm=op_HadamardScans(raw_mm,[-1 1],'diff1');
566	%                     diff1_mm = op_takesubspec(raw_mm,3);
567	%                     [diff1_mm,~]          = op_autophase(diff1_mm,0.5,1.1);
568	%                     raw_mm = op_mergesubspec(raw_mm,diff1_mm);
569	%                     [refShift_mm, ~] = fit_OspreyReferencingMM(raw_mm);
570	%                     [raw_mm]             = op_freqshift(raw_mm,-refShift_mm);
571	                    switch MRSCont.opts.SubSpecAlignment.mm
572	                        case 'L1Norm'
573	                        [raw_mm]  = osp_editSubSpecAlignLNorm(raw_mm,seq);
574	                        case 'L2Norm'
575	                        [raw_mm]  = osp_editSubSpecAlign(raw_mm, seq, target,MRSCont.opts.UnstableWater);
576	                        otherwise
577	                    end
578	                    if switchOrder
579	                        raw_mm.flags.orderswitched = 1;
580	                    else
581	                        raw_mm.flags.orderswitched = 0;
582	                    end
583	                    raw_mm=op_HadamardScans(raw_mm,[-1 1],'diff1');
584	                    raw_mm=op_HadamardScans(raw_mm,[1 1],'sum');
585	                end
586	                % Create the edited difference spectrum
587	                raw=op_HadamardScans(raw,[-1 1],'diff1');
588	                % Create the sum spectrum
589	                raw=op_HadamardScans(raw,[1 1],'sum');
590	                raw.target = target;
591	                raw = op_freqshift(raw, refShift_SubSpecAlign);
592	            end
593	
594	            if raw.flags.isHERMES || raw.flags.isHERCULES
595	                % Create all Hadamard combinations to generate a well defined
596	                % raw struct
597	                if ~exist('target3', 'var')
598	                    raw=op_HadamardScans(raw,[-1 1 -1 1],'diff1');
599	                    raw=op_HadamardScans(raw,[-1 -1 1 1],'diff2');
600	                else  % For HERMES 4 acqusitions
601	                    raw=op_HadamardScans(raw,[-1 1 -1 1],'diff1');
602	                    raw=op_HadamardScans(raw,[-1 -1 1 1],'diff2');
603	                    raw=op_HadamardScans(raw,[-1 1 1 -1],'diff3');
604	                end
605	                raw=op_HadamardScans(raw,[1 1 1 1],'sum');
606	                raw_no_subspec_aling = raw;
607	
608	                % Correct the frequency axis so that Cr appears at 3.027 ppm
609	                [refShift_SubSpecAlign, ~] = osp_XReferencing(raw,[3.03 3.22],[1 1],[1.85 3.9]);% determine frequency shift
610	                if abs(refShift_SubSpecAlign) > 10 % This a huge shift. Most likley wrong and we will try it again with tNAA only
611	                    [refShift_SubSpecAlign, ~] = osp_XReferencing(raw,2.01,1,[1.85 3.9]);% determine frequency shift
612	                end
613	
614	                % Apply initial referencing shift
615	                raw = op_freqshift(raw, -refShift_SubSpecAlign);
616	                % Fit a double-Lorentzian to the Cr-Cho area, and phase the spectrum
617	                % with the negative phase of that fit
618	                [raw,~] = op_phaseCrCho(raw, 1);
619	                % Align the sub-spectra to one another by minimizing the difference
620	                % between the common 'reporter' signals.
621	                switch MRSCont.opts.SubSpecAlignment.mets
622	                    case 'L1Norm'
623	                        [raw]  = osp_editSubSpecAlignLNorm(raw,seq);
624	                    case 'L2Norm'
625	                        if ~exist('target3', 'var')
626	                            [raw]  = osp_editSubSpecAlign(raw, seq, target1,target2,MRSCont.opts.UnstableWater);
627	                        else
628	                            if strcmp(target3,'EtOH')
629	                                [raw]  = osp_editSubSpecAlign(raw, seq, target1,target3,MRSCont.opts.UnstableWater);
630	                            else
631	                               [raw]  = osp_editSubSpecAlign(raw, seq, target2,target3,MRSCont.opts.UnstableWater); 
632	                            end
633	                        end
634	                    otherwise
635	                end
636	                % Update all Hadamard combinations after subspectra alignment
637	                if ~exist('target3', 'var')
638	                    raw=op_HadamardScans(raw,[-1 1 -1 1],'diff1');
639	                    raw=op_HadamardScans(raw,[-1 -1 1 1],'diff2');
640	                else  % For HERMES 4 acqusitions
641	                    raw=op_HadamardScans(raw,[-1 1 -1 1],'diff1');
642	                    raw=op_HadamardScans(raw,[-1 -1 1 1],'diff2');
643	                    raw=op_HadamardScans(raw,[-1 1 1 -1],'diff3');
644	                end
645	                raw=op_HadamardScans(raw,[1 1 1 1],'sum');
646	                raw = op_freqshift(raw, refShift_SubSpecAlign);
647	                fields.Method   = 'Addition of sub-spectra';
648	                if raw.flags.isHERCULES
649	                    fields.Details  = ['HERCULES Hadmard combination (Oeltzschner et al. 2019)'];
650	                else
651	                    fields.Details  = ['HERMES Hadmard combination (Saleh et al. 2018)'];
652	                end
653	                raw = op_add_analysis_provenance(raw,fields);
654	                
655	            end
656	            
657	%%          %%% 7. REMOVE RESIDUAL WATER %%%
658	            % Define different water removal frequency ranges, depending on
659	            % whether this is phantom data
660	            if MRSCont.flags.isPhantom
661	                waterRemovalFreqRange = [4.5 5];
662	                fracFID = 0.2;
663	            else
664	                waterRemovalFreqRange = [4.2 4.9];
665	                fracFID = 0.75;
666	            end
667	            % Apply iterative water filter
668	            raw = op_iterativeWaterFilter(raw, waterRemovalFreqRange, 32, fracFID*length(raw.fids), 0);
669	            if exist('raw_no_subspec_aling','var')
670	                raw_no_subspec_aling = op_iterativeWaterFilter(raw_no_subspec_aling, waterRemovalFreqRange, 32, fracFID*length(raw.fids), 0);
671	            end
672	
673	            if MRSCont.flags.hasMM %re_mm
674	                raw_mm = op_iterativeWaterFilter(raw_mm, waterRemovalFreqRange, 32, fracFID*length(raw_mm.fids), 0);
675	            end
676	
677	%%          %%% 8. REFERENCE SPECTRUM CORRECTLY TO FREQUENCY AXIS AND PHASE SIEMENS
678	            %%% DATA
679	            if MRSCont.flags.isPhantom
680	                [refShift, ~, ~] = osp_PhantomReferencing(raw);
681	            else
682	                [refShift, ~] = osp_XReferencing(raw,[3.03 3.22],[1 1],[1.85 4.2]);% determine frequency shift
683	                if abs(refShift) > 10 % This a huge shift. Most likley wrong and we will try it again with tNAA only
684	                    [refShift, ~] = osp_XReferencing(raw,2.01,1,[1.85 4.2]);% determine frequency shift
685	                end
686	            end
687	            [raw]             = op_freqshift(raw,-refShift);            % Reference spectra by cross-correlation
688	            if exist('raw_no_subspec_aling','var')
689	                [raw_no_subspec_aling]             = op_freqshift(raw_no_subspec_aling,-refShift);            % Reference spectra by cross-correlation
690	            end
691	
692	            if MRSCont.flags.hasMM %re_mm
693	                if raw_mm.flags.isMEGA
694	                    temp = op_takesubspec(raw_mm,3);
695	                    [temp,~]          = op_autophase(temp,0.5,1.1);
696	                    raw_mm = op_mergesubspec(raw_mm,temp);
697	                end
698	                [refShift_mm, ~] = fit_OspreyReferencingMM(raw_mm);
699	                [raw_mm]             = op_freqshift(raw_mm,-refShift_mm);            % Reference spectra by cross-correlation
700	            end
701	
702	            % Save back to MRSCont container
703	            if (strcmp(MRSCont.vendor,'Siemens') && raw.flags.isUnEdited && ~MRSCont.flags.isPhantom) || MRSCont.flags.isMRSI
704	                % Fit a double-Lorentzian to the Cr-Cho area, and phase the spectrum
705	                % with the negative phase of that fit
706	                [raw,globalPhase]       = op_phaseCrCho(raw, 1);
707	                raw.specReg{1}.phs = raw.specReg{1}.phs - globalPhase*180/pi;
708	            end
709	
710	%%          %%% 9. QUALITY CONTROL PARAMETERS %%%
711	            SubSpec = raw.names;
712	            % Calculate some spectral quality metrics here;
713	            [raw,SNR] = op_get_Multispectra_SNR(raw);
714	            FWHM = op_get_Multispectra_LW(raw);
715	            MRSCont.processed.metab{metab_ll,kk}     = raw;
716	            if exist('raw_no_subspec_aling','var')
717	                MRSCont.processed_no_align.metab{metab_ll,kk}     = raw_no_subspec_aling;
718	            end
719	            for ss = 1 : length(SubSpec)
720	                MRSCont.QM.SNR.metab(metab_ll,kk,ss)    = SNR{ss};
721	                MRSCont.QM.FWHM.metab(metab_ll,kk,ss)   = FWHM(ss); % in Hz
722	                MRSCont.QM.freqShift.metab(metab_ll,kk,ss)  = refShift;
723	                MRSCont.QM.res_water_amp.metab(metab_ll,kk,ss) = sum(MRSCont.processed.metab{kk}.watersupp{ss}.amp);
724	                if strcmp(SubSpec{ss},'diff1') ||strcmp(SubSpec{ss},'diff2') || strcmp(SubSpec{ss},'diff3') ||strcmp(SubSpec{ss},'sum')
725	                    if raw.flags.isMEGA
726	                        MRSCont.QM.drift.pre.(SubSpec{ss}){metab_ll,kk}  = reshape([MRSCont.QM.drift.pre.A{kk}'; MRSCont.QM.drift.pre.B{kk}'], 1, [])';
727	                        MRSCont.QM.drift.post.(SubSpec{ss}){metab_ll,kk} = reshape([MRSCont.QM.drift.post.A{kk}'; MRSCont.QM.drift.post.B{kk}'], 1, [])';
728	                    else
729	                        MRSCont.QM.drift.pre.(SubSpec{ss}){metab_ll,kk}  = reshape([MRSCont.QM.drift.pre.A{kk}'; MRSCont.QM.drift.pre.B{kk}'; MRSCont.QM.drift.pre.C{kk}'; MRSCont.QM.drift.pre.D{kk}'], 1, [])';
730	                        MRSCont.QM.drift.post.(SubSpec{ss}){metab_ll,kk} = reshape([MRSCont.QM.drift.post.A{kk}'; MRSCont.QM.drift.post.B{kk}'; MRSCont.QM.drift.post.C{kk}'; MRSCont.QM.drift.post.D{kk}'], 1, [])';
731	                    end
732	                end
733	                MRSCont.QM.drift.pre.AvgDeltaCr.(SubSpec{ss})(metab_ll,kk) = mean(MRSCont.QM.drift.pre.(SubSpec{ss}){kk} - 3.02);
734	                MRSCont.QM.drift.post.AvgDeltaCr.(SubSpec{ss})(metab_ll,kk) = mean(MRSCont.QM.drift.post.(SubSpec{ss}){kk} - 3.02);
735	            end
736	            if MRSCont.flags.hasMM
737	                SubSpec = raw_mm.names;
738	                [raw_mm,SNR] = op_get_Multispectra_SNR(raw_mm,1);
739	                FWHM = op_get_Multispectra_LW(raw_mm);

1	function [out] = osp_editSubSpecAlign(varargin)
2	%% [varargout] = osp_editSubSpecAlign(varargin)
3	%   Aligns sub-spectra of (multiplexed) edited MRS data to minimize
4	%   subtraction artefacts.
5	%
6	%   USAGE:
7	%       [outA, outB, outC, outD] = osp_editSubSpecAlign(in, seq, target,unstableWater);
8	%
9	%   INPUTS:
10	%       in        = Input data structure with sub-spectrum A.
11	%       seq       = sequence type
12	%       target     = String. Can be 'GABA' or 'GSH'. (necessary if only two
13	%                    inputs inA and inB are provided)
14	%       unstableWater = Flag for unstable residual water. This ignores
15	%                       water for the optimization and uses Choline instead
16	%
17	%   OUTPUTS:
18	%       outA       = Output following alignment of averages.
19	%       outB       = Output following alignment of averages.
20	%       outC       = Output following alignment of averages. (optional)
21	%       outD       = Output following alignment of averages. (optional)
22	%
23	%   AUTHOR:
24	%       Dr. Georg Oeltzschner (Johns Hopkins University, 2019-08-15)
25	%       goeltzs1@jhmi.edu
26	%       Dr. Mark Mikkelsen (Johns Hopkins University)
27	%       mmikkel5@jhmi.edu
28	%   
29	%   CREDITS:    
30	%       This code is based on numerous functions from the FID-A toolbox by
31	%       Dr. Jamie Near (McGill University)
32	%       https://github.com/CIC-methods/FID-A
33	%       Simpson et al., Magn Reson Med 77:23-33 (2017)
34	%
35	%   HISTORY:
36	%       2019-08-15: First version of the code.
37	
38	
39	% Determine whether there are 2 (MEGA) or 4 (HERMES/HERCULES) inputs
40	if nargin == 5
41	    in     = varargin{1};
42	    seqType = varargin{2};
43	    target1 = varargin{3};
44	    target2 = varargin{4};
45	    unstableWater = varargin{5};
46	elseif nargin == 4 && (strcmp(varargin{2},'HERMES') || strcmp(varargin{2},'HERCULES'))
47	    in     = varargin{1};
48	    seqType = varargin{2};
49	    target1 = varargin{3};
50	    target2 = varargin{4};
51	    unstableWater = 0;
52	elseif nargin == 4
53	    in     = varargin{1};
54	    seqType = varargin{2};
55	    target = varargin{3};
56	    unstableWater = varargin{4};
57	elseif nargin == 3 && strcmp(varargin{2},'MEGA')
58	    in     = varargin{1};
59	    seqType = varargin{2};
60	    target  = varargin{3};
61	    unstableWater = 0;
62	else
63	    error('Error in osp_editSubSpecAlign! For provide raw data struct, the sequence type, the name of the editing target, and the optional unstable water flag.')
64	end
65	
66	% Check whether data is coil-combined. If not, throw error.
67	if ~in.flags.addedrcvrs
68	    error('ERROR:  I think it only makes sense to do this after you have combined the channels using op_addrcvrs.  ABORTING!!');
69	end
70	
71	% Check whether data is averaged. If not, throw error.
72	if ~in.flags.averaged
73	    error('ERROR:  I think it only makes sense to do this after averaging using op_averaging.  ABORTING!!');
74	end
75	
76	switch seqType
77	   case 'MEGA'
78	        inA=op_takesubspec(in,1);
79	        inB=op_takesubspec(in,2);
80	    case 'HERMES'
81	        inA=op_takesubspec(in,1);
82	        inB=op_takesubspec(in,2);
83	        inC=op_takesubspec(in,3);
84	        inD=op_takesubspec(in,4);
85	    case 'HERCULES'
86	        inA=op_takesubspec(in,1);
87	        inB=op_takesubspec(in,2);
88	        inC=op_takesubspec(in,3);
89	        inD=op_takesubspec(in,4);
90	end
91	        
92	    
93	%%% 1. SET UP REQUIRED VARIABLES %%%
94	% Define the frequency ranges over which water, NAA, and Cho subtraction artefacts
95	% are to be minimized. Also, get a good starting estimate for the frequency
96	% alignment shift by determining the difference between the two maxima in
97	% the respective peak range (water, NAA, or Cho).
98	freq = inA.ppm;
99	% Water
100	freqLim(1,:) = freq <= 4.68+0.22 & freq >= 4.68-0.22;
101	[~,i] = max([abs(real(inA.specs(freqLim(1,:)))) abs(real(inB.specs(freqLim(1,:))))]);
102	freq2 = freq(freqLim(1,:));
103	maxFreq = freq2(i);
104	for jj = 1:2
105	    tmp(jj,:) = freq <= maxFreq(jj)+0.22 & freq >= maxFreq(jj)-0.22;
106	end
107	freqLim(1,:) = or(tmp(1,:), tmp(2,:));
108	f0 = (maxFreq(1) - maxFreq(2)) * inA.txfrq*1e-6;
109	x0(1,:) = [f0 0];
110	    
111	% NAA
112	freqLim(2,:) = freq <= 2.01+0.13 & freq >= 2.01-0.13;
113	peaks = '2.01 ppm (A/B)';
114	switch seqType
115	    case 'HERCULES'
116	        [~,i] = max([abs(real(inA.specs(freqLim(2,:)))) abs(real(inC.specs(freqLim(2,:))))]);
117	    case 'HERMES'
118	        [~,i] = max([abs(real(inA.specs(freqLim(2,:)))) abs(real(inC.specs(freqLim(2,:))))]);
119	    case 'MEGA'
120	        [~,i] = max([abs(real(inA.specs(freqLim(2,:)))) abs(real(inB.specs(freqLim(2,:))))]);
121	end
122	freq2 = freq(freqLim(2,:));
123	maxFreq = freq2(i);
124	for jj = 1:2
125	    tmp(jj,:) = freq <= maxFreq(jj)+0.13 & freq >= maxFreq(jj)-0.13;
126	end
127	freqLim(2,:) = or(tmp(1,:), tmp(2,:));
128	f0 = (maxFreq(1) - maxFreq(2)) * inA.txfrq*1e-6;
129	x0(2,:) = [f0 0];
130	
131	% In case the water peak is not well-behaved and has several peaks we are
132	% possibly detecting several peaks. This will lead to unreasonable shifts
133	% between the sub-spectra. In this case, we use the Choline peak.
134	if unstableWater
135	
136	    freqLim(1,:) = freq <= 3.22+0.09 & freq >= 3.22-0.09;
137	    [~,i] = max([abs(real(inA.specs(freqLim(1,:)))) abs(real(inB.specs(freqLim(1,:))))]);
138	    freq2 = freq(freqLim(1,:));
139	    maxFreq = freq2(i);
140	    for jj = 1:2
141	        tmp(jj,:) = freq <= maxFreq(jj)+0.08 & freq >= maxFreq(jj)-0.08;
142	    end
143	    freqLim(1,:) = or(tmp(1,:), tmp(2,:));
144	    f0 = (maxFreq(1) - maxFreq(2)) * inA.txfrq*1e-6;
145	    x0(1,:) = [f0 0];
146	
147	end
148	
149	% Optimization options
150	lsqnonlinopts = optimoptions(@lsqnonlin);
151	lsqnonlinopts = optimoptions(lsqnonlinopts,'Display','off','Algorithm','levenberg-marquardt');
152	
153	% Initialize common variables
154	t           = inA.t;
155	
156	
157	%%% 2. PERFORM ALIGNMENT BASED ON SEQUENCE TYPE
158	if strcmp(seqType, 'HERMES') || strcmp(seqType, 'HERCULES') 
159	    if ~(exist('target1','var') && exist('target2','var'))
160	        %Fall back into default HERMES GABA GSH editing
161	        target1 = 'GABA';
162	        target2 = 'GSH';
163	    end
164	    
165	    target = [target1 target2];
166	    switch target
167	        case {'GABAGSH','GABALac','GABAEtOH'}  
168	            % For HERMES/HERCULES data, align the GSH-OFF spectra first, i.e.
169	            % minimize the residual water peak in the difference between them.
170	
171	            % Determine normalization factor so that normalized spectra are entered
172	            % into the optimization
173	            a = max(max([abs(real(inA.specs)) abs(real(inB.specs))]));
174	            fun = @(x) objFunc(op_ampScale(inA, 1/a), op_ampScale(inB, 1/a), freqLim(1,:), t, x);
175	            param(1,:) = lsqnonlin(fun, x0(1,:), [], [], lsqnonlinopts);
176	            % Apply the calculated frequency/phase adjustment to the inB spectrum
177	            fidsB = inB.fids.*exp(1i*pi*(t'*param(1,1)*2+param(1,2)/180));
178	            specsB = fftshift(fft(fidsB, [], inB.dims.t), inB.dims.t);
179	            % Create output
180	            outA = inA;
181	            outB = inB;
182	            outB.fids = fidsB;
183	            outB.specs = specsB;
184	
185	            % Then, align the GABA-OFF spectra, i.e minimize the residual NAA peak
186	            % in the difference between them.
187	            % Determine normalization factor so that normalized spectra are entered
188	            % into the optimization
189	            a = max(max([abs(real(inA.specs)) abs(real(inC.specs))]));
190	            fun = @(x) objFunc(op_ampScale(inA, 1/a), op_ampScale(inC, 1/a), freqLim(2,:), t, x);
191	            param(2,:) = lsqnonlin(fun, x0(2,:), [], [], lsqnonlinopts);
192	            % Apply the calculated frequency/phase adjustment to the inC spectrum
193	            fidsC = inC.fids.*exp(1i*pi*(t'*param(2,1)*2+param(2,2)/180));
194	            specsC = fftshift(fft(fidsC, [], inC.dims.t), inC.dims.t);
195	            % Create output
196	            outC = inC;
197	            outC.fids = fidsC;
198	            outC.specs = specsC;
199	
200	            % Then, align the GABA-ON-GSH-ON spectra to the **corrected** GABA-OFF-GSH-ON
201	            % spectrum - this is something Mark/Georg independently from each other
202	            % found out to work best for HERMES/HERCULES data.
203	
204	            % Find Cho peak and get starting estimate for the frequency shift
205	            freqLim(3,:) = freq <= 3.2+0.09 & freq >= 3.2-0.09;
206	            [~,i] = max([abs(real(outC.specs(freqLim(3,:)))) abs(real(inD.specs(freqLim(3,:))))]);
207	            freq2 = freq(freqLim(3,:));
208	            maxFreq = freq2(i);
209	            for jj = 1:2
210	                tmp(jj,:) = freq <= maxFreq(jj)+0.08 & freq >= maxFreq(jj)-0.08;
211	            end
212	            freqLim(3,:) = or(tmp(1,:), tmp(2,:));
213	            f0 = (maxFreq(1) - maxFreq(2)) * inA.txfrq*1e-6;
214	            x0(3,:) = [f0 0];
215	
216	            % Determine normalization factor so that normalized spectra are entered
217	            % into the optimization
218	            a = max(max([abs(real(outC.specs)) abs(real(inD.specs))]));
219	            fun = @(x) objFunc(op_ampScale(outC, 1/a), op_ampScale(inD, 1/a), freqLim(3,:), t, x);
220	            param(3,:) = lsqnonlin(fun, x0(3,:), [], [], lsqnonlinopts);
221	            % Apply the calculated frequency/phase adjustment to the inD spectrum
222	            fidsD = inD.fids.*exp(1i*pi*(t'*param(3,1)*2+param(3,2)/180));
223	            specsD = fftshift(fft(fidsD, [], inD.dims.t), inD.dims.t);
224	
225	            % Create output
226	            outD = inD;
227	            outD.fids = fidsD;
228	            outD.specs = specsD;
229	        
230	        case 'NAANAAG' 
231	            % For HERMES/HERCULES data, align the GSH-OFF spectra first, i.e.
232	            % minimize the residual water peak in the difference between them.
233	            % NAA
234	            freqLim(1,:) = freq <= 2.01+0.13 & freq >= 2.01-0.13;
235	            [~,i] = max([abs(real(inA.specs(freqLim(1,:)))) abs(real(inB.specs(freqLim(1,:))))]);
236	            freq2 = freq(freqLim(1,:));
237	            maxFreq = freq2(i);
238	            for jj = 1:2
239	                tmp(jj,:) = freq <= maxFreq(jj)+0.13 & freq >= maxFreq(jj)-0.13;
240	            end
241	            freqLim(1,:) = or(tmp(1,:), tmp(2,:));
242	            f0 = (maxFreq(1) - maxFreq(2)) * inA.txfrq*1e-6;
243	            x0(1,:) = [f0 0];
244	            % Determine normalization factor so that normalized spectra are entered
245	            % into the optimization
246	            a = max(max([abs(real(inA.specs)) abs(real(inB.specs))]));
247	            fun = @(x) objFunc(op_ampScale(inA, 1/a), op_ampScale(inB, 1/a), freqLim(1,:), t, x);
248	            param(1,:) = lsqnonlin(fun, x0(1,:), [], [], lsqnonlinopts);
249	            % Apply the calculated frequency/phase adjustment to the inB spectrum
250	            fidsB = inB.fids.*exp(1i*pi*(t'*param(1,1)*2+param(1,2)/180));
251	            specsB = fftshift(fft(fidsB, [], inB.dims.t), inB.dims.t);
252	            % Create output
253	            outA = inA;
254	            outB = inB;
255	            outB.fids = fidsB;
256	            outB.specs = specsB;
257	
258	            % Then, align the GABA-OFF spectra, i.e minimize the residual NAA peak
259	            % in the difference between them.
260	            % Determine normalization factor so that normalized spectra are entered
261	            % into the optimization
262	            a = max(max([abs(real(inA.specs)) abs(real(inC.specs))]));
263	            fun = @(x) objFunc(op_ampScale(inA, 1/a), op_ampScale(inC, 1/a), freqLim(2,:), t, x);
264	            param(2,:) = lsqnonlin(fun, x0(2,:), [], [], lsqnonlinopts);
265	            % Apply the calculated frequency/phase adjustment to the inC spectrum
266	            fidsC = inC.fids.*exp(1i*pi*(t'*param(2,1)*2+param(2,2)/180));
267	            specsC = fftshift(fft(fidsC, [], inC.dims.t), inC.dims.t);
268	            % Create output
269	            outC = inC;
270	            outC.fids = fidsC;
271	            outC.specs = specsC;
272	
273	            % Then, align the GABA-ON-GSH-ON spectra to the **corrected** GABA-OFF-GSH-ON
274	            % spectrum - this is something Mark/Georg independently from each other
275	            % found out to work best for HERMES/HERCULES data.
276	
277	            % Find Cho peak and get starting estimate for the frequency shift
278	            freqLim(3,:) = freq <= 2.01+0.13 & freq >= 2.01-0.13;
279	            [~,i] = max([abs(real(outC.specs(freqLim(3,:)))) abs(real(inD.specs(freqLim(3,:))))]);
280	            freq2 = freq(freqLim(3,:));
281	            maxFreq = freq2(i);
282	            for jj = 1:2
283	                tmp(jj,:) = freq <= maxFreq(jj)+0.13 & freq >= maxFreq(jj)-0.13;
284	            end
285	            freqLim(3,:) = or(tmp(1,:), tmp(2,:));
286	            f0 = (maxFreq(1) - maxFreq(2)) * inA.txfrq*1e-6;
287	            x0(3,:) = [f0 0];
288	
289	            % Determine normalization factor so that normalized spectra are entered
290	            % into the optimization
291	            a = max(max([abs(real(outC.specs)) abs(real(inD.specs))]));
292	            fun = @(x) objFunc(op_ampScale(outC, 1/a), op_ampScale(inD, 1/a), freqLim(3,:), t, x);
293	            param(3,:) = lsqnonlin(fun, x0(3,:), [], [], lsqnonlinopts);
294	            % Apply the calculated frequency/phase adjustment to the inD spectrum
295	            fidsD = inD.fids.*exp(1i*pi*(t'*param(3,1)*2+param(3,2)/180));
296	            specsD = fftshift(fft(fidsD, [], inD.dims.t), inD.dims.t);
297	
298	            % Create output
299	            outD = inD;
300	            outD.fids = fidsD;
301	            outD.specs = specsD;
302	    end
303	    % Create output
304	    out = op_mergesubspec(outA,outB,outC,outD);
305	
306	    % Add NIfTI-MRS provenance
307	    % Generate fields for provenance
308	    if unstableWater
309	       peaks = '3.2 ppm (A/B), 2.01 ppm (B/C), 3.2 (C/D)';
310	    else
311	       peaks = '4.68 ppm (A/B), 2.01 ppm (B/C), 3.2 (C/D)';
312	    end
313	    fields.Method   = 'Aligment of subtraction sub-spectra';
314	    fields.Details  = ['L2 optimization of HADAMARD spectra (Mikkelsen et al. 2018), dim = DIM_EDIT, reference = ' peaks];
315	    out = op_add_analysis_provenance(out,fields);
316	    
317	elseif strcmp(seqType, 'MEGA')
318	    % For MEGA-edited data, the 'reporter signal' that is used to align the
319	    % two sub-spectra will depend on the edited metabolite. Since the peak
320	    % needs to be identical in both acquisitions, we choose the residual
321	    % water peak for GABA-edited data, and the NAA peak for GSH-edited
322	    % data.
323	    switch target
324	        case 'GABA'
325	            % For GABA-edited data, align the GABA-ON spectrum using the
326	            % residual water peak.
327	            % Determine normalization factor so that normalized spectra are entered
328	            % into the optimization
329	            a = max(max([abs(real(inA.specs)) abs(real(inB.specs))]));
330	            fun = @(x) objFunc(op_ampScale(inA, 1/a), op_ampScale(inB, 1/a), freqLim(1,:), t, x);
331	            param(1,:) = lsqnonlin(fun, x0(1,:), [], [], lsqnonlinopts);
332	            peaks = '4.7 ppm (A/B)';
333	
334	        case 'GSH'
335	            % For GSH-edited data, align the GSH-ON spectrum using the
336	            % NAA peak.
337	            % Determine normalization factor so that normalized spectra are entered
338	            % into the optimization
339	            a = max(max([abs(real(inA.specs)) abs(real(inB.specs))]));
340	            fun = @(x) objFunc(op_ampScale(inA, 1/a), op_ampScale(inB, 1/a), freqLim(2,:), t, x);
341	            param(1,:) = lsqnonlin(fun, x0(2,:), [], [], lsqnonlinopts);
342	            
343	        case 'Lac'
344	            % For Lac-edited data, align the Lac-ON spectrum using the
345	            % NAA peak.
346	            % Determine normalization factor so that normalized spectra are entered
347	            % into the optimization
348	            a = max(max([abs(real(inA.specs)) abs(real(inB.specs))]));
349	            fun = @(x) objFunc(op_ampScale(inA, 1/a), op_ampScale(inB, 1/a), freqLim(2,:), t, x);
350	            param(1,:) = lsqnonlin(fun, x0(2,:), [], [], lsqnonlinopts);
351	
352	        case 'PE322'
353	            % For Lac-edited data, align the Lac-ON spectrum using the
354	            % NAA peak.
355	            % Determine normalization factor so that normalized spectra are entered
356	            % into the optimization
357	            a = max(max([abs(real(inA.specs)) abs(real(inB.specs))]));
358	            fun = @(x) objFunc(op_ampScale(inA, 1/a), op_ampScale(inB, 1/a), freqLim(2,:), t, x);
359	            param(1,:) = lsqnonlin(fun, x0(2,:), [], [], lsqnonlinopts);
360	 
361	        case 'PE398'
362	            % For Lac-edited data, align the Lac-ON spectrum using the
363	            % NAA peak.
364	            % Determine normalization factor so that normalized spectra are entered
365	            % into the optimization
366	            a = max(max([abs(real(inA.specs)) abs(real(inB.specs))]));
367	            fun = @(x) objFunc(op_ampScale(inA, 1/a), op_ampScale(inB, 1/a), freqLim(2,:), t, x);
368	            param(1,:) = lsqnonlin(fun, x0(2,:), [], [], lsqnonlinopts);
369	
370	            
371	        otherwise
372	            error('Error in osp_editSubSpecAlign! Target string not recognized.');
373	    end
374	
375	    % Apply the calculated frequency/phase adjustment to the inB spectrum
376	    fidsB = inB.fids.*exp(1i*pi*(t'*param(1,1)*2+param(1,2)/180));
377	    specsB = fftshift(fft(fidsB, [], inB.dims.t), inB.dims.t);
378	    
379	    % Create output
380	    outA = inA;
381	    outB = inB;
382	    outB.fids = fidsB;
383	    outB.specs = specsB;
384	    out=op_mergesubspec(outA,outB);
385	
386	    % Add NIfTI-MRS provenance
387	    % Generate fields for provenance
388	    if unstableWater
389	       peaks = '3.68 ppm (A/B)';
390	    end
391	    fields.Method   = 'Aligment of subtraction sub-spectra';
392	    fields.Details  = ['L2 optimization of ON/OFF spectra (Mikkelsen et al. 2018), dim = DIM_EDIT, reference = ' peaks];
393	    out = op_add_analysis_provenance(out,fields);
394	
395	    varargout{1} = out;
396	    
397	end
398	
399	end
