402	function out = objFunc(in1, in2, freqLim, t, x)
403	
404	% This is the objective function that minimizes the difference over the 
405	% frequency range (freqLim) between the target spectrum (in1) and the 
406	% spectrum that is to be frequency-and-phase aligned (in2).
407	
408	f   = x(1); % frequency correction
409	phi = x(2); % phase correction
410	
411	y1 = in1.fids;
412	y2 = in2.fids .* exp(1i*pi*(t'*f*2+phi/180)); % apply to time-domain data
413	
414	% fft
415	a = real(fftshift(fft(y1,[],1),1));
416	b = real(fftshift(fft(y2,[],1),1));
417	
418	% return difference vector over defined frequency range
419	DIFF = a - b;
420	out = DIFF(freqLim);
421	
422	end

1	function [varargout] = osp_editSubSpecAlignLNorm(varargin)
2	%% [varargout] = osp_editSubSpecAlign(varargin)
3	%   Aligns sub-spectra of edited MRS data to minimize
4	%   subtraction artefacts. It uses a L1 Norm minimization including the
5	%   whole frequency range (Cleve et al., JMR, 2017 (https://doi.org/10.1016/j.jmr.2017.04.004) .
6	%
7	%   USAGE:
8	%       [outA, outB] = osp_editSubSpecAlign(inA, inB/target);
9	%
10	%   INPUTS:
11	%       inA        = Input data structure A.
12	%       inB        = Input data structure B. (optional)
13	%
14	%   OUTPUTS:
15	%       outA       = Output following alignment of averages.
16	%       outB       = Output following alignment of averages. (optional)
17	%
18	%   AUTHOR:
19	%       Dr. Helge Zollner (Johns Hopkins University, 2021-03-01)
20	%       hzoelln2@jhmi.edu
21	%   
22	%   CREDITS:    
23	%       This code is based on numerous functions from the FID-A toolbox by
24	%       Dr. Jamie Near (McGill University)
25	%       https://github.com/CIC-methods/FID-A
26	%       Simpson et al., Magn Reson Med 77:23-33 (2017)
27	%
28	%   HISTORY:
29	%       2021-01-01: First version of the code.
30	
31	% Determine whether there are 2 (MEGA) or 4 (HERMES/HERCULES) inputs
32	if nargin == 2 && isstruct(varargin{2})
33	    seqType = 'MEGA';
34	    inA     = varargin{1};
35	    inB     = varargin{2};
36	    if inA.subspecs > 1 || inB.subspecs > 1
37	        error('Error in osp_editSubSpecAlign! Both data structs must have only 1 sub-spectrum');
38	    end
39	elseif nargin == 2 && ~isstruct(varargin{2})
40	    in     = varargin{1};
41	    seqType = varargin{2};
42	    if in.subspecs == 1
43	        error('Error in osp_editSubSpecAlign! The data struct must have > 1 sub-spectrum');
44	    end
45	    switch seqType
46	        case 'MEGA'
47	            inA=op_takesubspec(in,1);
48	            inB=op_takesubspec(in,2);
49	        case 'HERMES'
50	            inA=op_takesubspec(in,1);
51	            inB=op_takesubspec(in,2);
52	            inC=op_takesubspec(in,3);
53	            inD=op_takesubspec(in,4);
54	        case 'HERCULES'
55	            inA=op_takesubspec(in,1);
56	            inB=op_takesubspec(in,2);
57	            inC=op_takesubspec(in,3);
58	            inD=op_takesubspec(in,4);
59	    end
60	else
61	    error('Error in osp_editSubSpecAlign! Needs to have either 2 spectra to align or one spectrum with sub-spectra and sequence type');
62	end
63	
64	% Check whether data is coil-combined. If not, throw error.
65	if ~in.flags.addedrcvrs
66	    error('ERROR:  I think it only makes sense to do this after you have combined the channels using op_addrcvrs.  ABORTING!!');
67	end
68	
69	% Check whether data is averaged. If not, throw error.
70	if ~in.flags.averaged
71	    error('ERROR:  I think it only makes sense to do this after averaging using op_averaging.  ABORTING!!');
72	end
73	
74	
75	
76	
77	%%% 1. SET UP REQUIRED VARIABLES %%%
78	% Define the frequency ranges over which water, NAA, and Cho subtraction artefacts
79	% are to be minimized. Also, get a good starting estimate for the frequency
80	% alignment shift by determining the difference between the two maxima in
81	% the respective peak range (water, NAA, or Cho).
82	freq = inA.ppm;
83	freqLim(1,:) = freq <= 4 & freq >= 1.95;
84	x0(1,:) = [0 0];
85	
86	
87	% Optimization options
88	lsqnonlinopts = optimoptions(@lsqnonlin);
89	lsqnonlinopts = optimoptions(lsqnonlinopts,'Display','off','Algorithm','levenberg-marquardt');
90	
91	% Initialize common variables
92	t           = inA.t;
93	
94	
95	%%% 2. PERFORM ALIGNMENT BASED ON SEQUENCE TYPE
96	if strcmp(seqType, 'HERMES') || strcmp(seqType, 'HERCULES')
97	
98	
99	    a = max(max([abs(real(inA.specs)) abs(real(inB.specs))]));
100	    fun = @(x) objFunc(op_ampScale(inA, 1/a), op_ampScale(inB, 1/a), freqLim(1,:), t, x);
101	    param(1,:) = lsqnonlin(fun, x0(1,:), [], [], lsqnonlinopts);
102	    % Apply the calculated frequency/phase adjustment to the inB spectrum
103	    fidsB = inB.fids.*exp(1i*pi*(t'*param(1,1)*2+param(1,2)/180));
104	    specsB = fftshift(fft(fidsB, [], inB.dims.t), inB.dims.t);
105	    % Create output
106	    outA = inA;
107	    outB = inB;
108	    outB.fids = fidsB;
109	    outB.specs = specsB;
110	
111	    a = max(max([abs(real(inA.specs)) abs(real(inC.specs))]));
112	    fun = @(x) objFunc(op_ampScale(inA, 1/a), op_ampScale(inC, 1/a), freqLim(1,:), t, x);
113	    param(2,:) = lsqnonlin(fun, x0(1,:), [], [], lsqnonlinopts);
114	    % Apply the calculated frequency/phase adjustment to the inC spectrum
115	    fidsC = inC.fids.*exp(1i*pi*(t'*param(2,1)*2+param(2,2)/180));
116	    specsC = fftshift(fft(fidsC, [], inC.dims.t), inC.dims.t);
117	    % Create output
118	    outC = inC;
119	    outC.fids = fidsC;
120	    outC.specs = specsC;
121	
122	    a = max(max([abs(real(outC.specs)) abs(real(inD.specs))]));
123	    fun = @(x) objFunc(op_ampScale(outC, 1/a), op_ampScale(inD, 1/a), freqLim(1,:), t, x);
124	    param(3,:) = lsqnonlin(fun, x0(1,:), [], [], lsqnonlinopts);
125	    % Apply the calculated frequency/phase adjustment to the inD spectrum
126	    fidsD = inD.fids.*exp(1i*pi*(t'*param(3,1)*2+param(3,2)/180));
127	    specsD = fftshift(fft(fidsD, [], inD.dims.t), inD.dims.t);
128	
129	    % Create output
130	    outD = inD;
131	    outD.fids = fidsD;
132	    outD.specs = specsD;
133	           
134	    % Create output
135	    merged = op_mergesubspec(outA,outB,outC,outD);
136	
137	    % Add NIfTI-MRS provenance
138	    % Generate fields for provenance
139	    fields.Method   = 'Aligment of subtraction sub-spectra';
140	    fields.Details  = ['L1 norm optimization of HADAMARD spectra (Cleve et al. 2017), dim = DIM_EDIT, frequency range (' num2str(1.95) ',' num2str(4) ') ppm'];
141	    merged = op_add_analysis_provenance(merged,fields);
142	
143	    varargout{1} = merged;
144	    
145	elseif strcmp(seqType, 'MEGA')
146	    % For MEGA-edited data, the 'reporter signal' that is used to align the
147	    % two sub-spectra will depend on the edited metabolite. Since the peak
148	    % needs to be identical in both acquisitions, we choose the residual
149	    % water peak for GABA-edited data, and the NAA peak for GSH-edited
150	    % data.
151	
152	    a = max(max([abs(real(inA.specs)) abs(real(inB.specs))]));
153	    fun = @(x) objFunc(op_ampScale(inA, 1/a), op_ampScale(inB, 1/a), freqLim(1,:), t, x);
154	    param(1,:) = lsqnonlin(fun, x0(1,:), [], [], lsqnonlinopts);
155	
156	    % Apply the calculated frequency/phase adjustment to the inB spectrum
157	    fidsB = inB.fids.*exp(1i*pi*(t'*param(1,1)*2+param(1,2)/180));
158	    specsB = fftshift(fft(fidsB, [], inB.dims.t), inB.dims.t);
159	    
160	    % Create output
161	    outA = inA;
162	    outB = inB;
163	    outB.fids = fidsB;
164	    outB.specs = specsB;
165	    if isstruct(varargin{2}) 
166	        % Add NIfTI-MRS provenance
167	        % Generate fields for provenance
168	        fields.Method   = 'Aligment of subtraction sub-spectra';
169	        fields.Details  = ['L1 norm optimization of ON/OFF spectra (Cleve et al. 2017), dim = DIM_EDIT, frequency range (' num2str(1.95) ',' num2str(4) ') ppm'];
170	        outA = op_add_analysis_provenance(outA,fields);
171	
172	        fields.Method   = 'Aligment of subtraction sub-spectra';
173	        fields.Details  = ['L1 norm optimization of ON/OFF spectra (Cleve et al. 2017), dim = DIM_EDIT, frequency range (' num2str(1.95) ',' num2str(4) ') ppm'];
174	        outB = op_add_analysis_provenance(outB,fields);
175	
176	        varargout{1} = outA;
177	        varargout{2} = outB;
178	    else
179	        merged = op_mergesubspec(outA,outB);
180	
181	        % Add NIfTI-MRS provenance
182	        % Generate fields for provenance
183	        fields.Method   = 'Aligment of subtraction sub-spectra';
184	        fields.Details  = ['L1 norm optimization of ON/OFF spectra (Cleve et al. 2017), dim = DIM_EDIT, frequency range (' num2str(1.95) ',' num2str(4) ') ppm'];
185	        merged = op_add_analysis_provenance(merged,fields);
186	    
187	        varargout{1} = merged;
188	    end
189	    
190	end
191	
192	end
