1	function [out, commuteOrder] = osp_onOffClassifyHERMES(in, target,Order)
2	%% [outA, outB, outC, outD, commuteOrder] = osp_onOffClassifyHERMES(in, target,Order)
3	%   This function decides how the four-provided HERMES/HERCULES sub-spectra are
4	%   being edited. Currently, this function works for all combinations of
5	%   HERMES and HERCULES that include GABA and GSH editing.
6	%   The NAA/NAAG/Asp-editing flavor of HERMES is currently not supported.
7	%
8	%   To determine the editing pattern, this function ranks the four spectra
9	%   according to the amplitude of the residual water (suppressed for GSH-ON)
10	%   and NAA (suppressed for GABA-ON) signals.
11	%
12	%   The function finally assigns:
13	%       - the GABA-OFF-GSH-OFF spectrum to field A
14	%       - the GABA-ON-GSH-OFF spectrum to field B
15	%       - the GABA-OFF-GSH-ON spectrum to field C
16	%       - the GABA-ON-GSH-ON spectrum to field D
17	%
18	%   USAGE:
19	%       [out] = osp_onOffClassifyHERMES(in, target,Order)
20	%
21	%   INPUTS:
22	%       in     = FID-A structure containing the all sub-spectra.
23	%       target = editing targets
24	%       Order  = manual overwrite order
25	%
26	%   OUTPUTS:
27	%       out    = FID-A structure containing sorted sub-spectra.
28	
29	%
30	%   AUTHOR:
31	%       Dr. Georg Oeltzschner (Johns Hopkins University, 2019-08-15)
32	%       goeltzs1@jhmi.edu
33	%
34	%   CREDITS:
35	%       This code is based on numerous functions from the FID-A toolbox by
36	%       Dr. Jamie Near (McGill University)
37	%       https://github.com/CIC-methods/FID-A
38	%       Simpson et al., Magn Reson Med 77:23-33 (2017)
39	%
40	%   HISTORY:
41	%       2019-08-15: First version of the code.
42	
43	if nargin < 2
44	    target = 'GABAGSH';
45	    Order = [];
46	end
47	if nargin < 3
48	    Order = [];
49	end
50	
51	if isempty(Order)
52	    inA = op_takesubspec(in,1);
53	    inB = op_takesubspec(in,2);
54	    inC = op_takesubspec(in,3);
55	    inD = op_takesubspec(in,4);
56	    
57	    
58	    switch target
59	        case 'GABAGSH'
60	            % Determine maximum signal intensities for water and NAA in each
61	            % sub-spectrum.
62	            [max_first(1), max_second(1)]  = findMaxNAAw(inA);
63	            [max_first(2), max_second(2)]  = findMaxNAAw(inB);
64	            [max_first(3), max_second(3)]  = findMaxNAAw(inC);
65	            [max_first(4), max_second(4)]  = findMaxNAAw(inD);
66	        case 'GABALac'
67	            [max_first(1), max_second(1)]  = findMaxNAACr(inA);
68	            [max_first(2), max_second(2)]  = findMaxNAACr(inB);
69	            [max_first(3), max_second(3)]  = findMaxNAACr(inC);
70	            [max_first(4), max_second(4)]  = findMaxNAACr(inD);
71	        otherwise
72	            [max_first(1), max_second(1)]  = findMaxNAAw(inA);
73	            [max_first(2), max_second(2)]  = findMaxNAAw(inB);
74	            [max_first(3), max_second(3)]  = findMaxNAAw(inC);
75	            [max_first(4), max_second(4)]  = findMaxNAAw(inD);
76	    end
77	    
78	    % Sort the intensities in ascending order
79	    [~,order_first]   = sort(max_first);
80	    [~,order_second] = sort(max_second);
81	    
82	    % Now loop over the subspectra indices (A = 1, B = 2, etc) to determine
83	    % whether the respective experiments have high or low intensities:
84	    for ll = 1:4
85	        idx_first   = find(order_first == ll);
86	        idx_second = find(order_second == ll);
87	    
88	        if ismember(idx_first,[3 4])
89	            first.ON(ll) = 0;
90	        elseif ismember(idx_first,[1 2])
91	            first.ON(ll) = 1;
92	        end
93	    
94	        if ismember(idx_second,[3 4])
95	            second.ON(ll) = 0;
96	        elseif ismember(idx_second,[1 2])
97	            second.ON(ll) = 1;
98	        end
99	    
100	    end
101	    
102	    % Determine the sub-spectra indices belonging to each editing pattern
103	    idx_OFF_OFF = ~second.ON & ~first.ON;
104	    idx_ON_OFF  = second.ON & ~first.ON;
105	    idx_OFF_ON  = ~second.ON & first.ON;
106	    idx_ON_ON   = second.ON & first.ON;
107	    
108	    % Commute for output
109	    try
110	        temp = in;
111	        out = in;
112	        out.specs(:,1) = temp.specs(:,idx_OFF_OFF);
113	        out.specs(:,2) = temp.specs(:,idx_ON_OFF);
114	        out.specs(:,3) = temp.specs(:,idx_OFF_ON);
115	        out.specs(:,4) = temp.specs(:,idx_ON_ON);
116	        out.fids(:,1) = temp.fids(:,idx_OFF_OFF);
117	        out.fids(:,2) = temp.fids(:,idx_ON_OFF);
118	        out.fids(:,3) = temp.fids(:,idx_OFF_ON);
119	        out.fids(:,4) = temp.fids(:,idx_ON_ON);
120	    catch
121	        idx_OFF_OFF = logical([0 0 0 1]);
122	        idx_ON_OFF  = logical([0 1 0 0]);
123	        idx_OFF_ON  = logical([1 0 0 0]);
124	        idx_ON_ON   = logical([0 0 1 0]);
125	        temp = in;
126	        out = in;
127	        out.specs(:,1) = temp.specs(:,idx_OFF_OFF);
128	        out.specs(:,2) = temp.specs(:,idx_ON_OFF);
129	        out.specs(:,3) = temp.specs(:,idx_OFF_ON);
130	        out.specs(:,4) = temp.specs(:,idx_ON_ON);
131	        out.fids(:,1) = temp.fids(:,idx_OFF_OFF);
132	        out.fids(:,2) = temp.fids(:,idx_ON_OFF);
133	        out.fids(:,3) = temp.fids(:,idx_OFF_ON);
134	        out.fids(:,4) = temp.fids(:,idx_ON_ON);
135	    end
136	    
137	    % Save commute order
138	    commuteOrder = [find(idx_OFF_OFF), find(idx_ON_OFF), find(idx_OFF_ON), find(idx_ON_ON)];
139	else
140	    temp = in;
141	    out = in;
142	    idx_OFF_OFF = logical([0 0 0 0]);
143	    idx_ON_OFF  = logical([0 0 0 0]);
144	    idx_OFF_ON  = logical([0 0 0 0]);
145	    idx_ON_ON   = logical([0 0 0 0]);
146	    idx_OFF_OFF(Order(1)) = 1;
147	    idx_ON_OFF(Order(2)) = 1;
148	    idx_OFF_ON(Order(3)) = 1;
149	    idx_ON_ON(Order(4)) = 1;
150	    out.specs(:,1) = temp.specs(:,idx_OFF_OFF);
151	    out.specs(:,2) = temp.specs(:,idx_ON_OFF);
152	    out.specs(:,3) = temp.specs(:,idx_OFF_ON);
153	    out.specs(:,4) = temp.specs(:,idx_ON_ON);
154	    out.fids(:,1) = temp.fids(:,idx_OFF_OFF);
155	    out.fids(:,2) = temp.fids(:,idx_ON_OFF);
156	    out.fids(:,3) = temp.fids(:,idx_OFF_ON);
157	    out.fids(:,4) = temp.fids(:,idx_ON_ON);
158	    % Save commute order
159	    commuteOrder = Order;
160	end
161	
162	end
