185	function [max_ins, max_NAA] = findMaxNAACr(in)
186	% This embedded function finds the maximum intensities of the creatine and
187	% siganls at 3.9 ppm and NAA signals of an input spectrum.
188	
189	% Determine relevant frequency ranges
190	out_ins   = op_freqrange(in,3.8,4);
191	out_NAA = op_freqrange(in,1.8,2.2);
192	
193	% Determine maximum absolute signal
194	max_ins   = max([abs(max(real(out_ins.specs))), abs(min(real(out_ins.specs)))]);
