1	function [MRSCont] = OspreySettings
2	%% [MRSCont] = OspreySettings
3	%   This function initialises default settings and variables required to
4	%   run Osprey.
5	%
6	%   USAGE:
7	%       [MRSCont] = OspreySettings;
8	%
9	%   OUTPUTS:
10	%       MRSCont     = Osprey MRS data container.
11	%
12	%   AUTHOR:
13	%       Dr. Georg Oeltzschner (Johns Hopkins University, 2019-02-18)
14	%       goeltzs1@jhmi.edu
15	%
16	%   HISTORY:
17	%       2019-02-19: First version of the code.
18	
19	close all;
20	
21	%%% 1. REQUIRED INPUT FLAGS %%%
22	% Initialise MRSCont struct with default settings
23	MRSCont = struct;
24	MRSCont.flags.isUnEdited            = 0;
25	MRSCont.flags.isMEGA                = 0;
26	MRSCont.flags.isHERMES              = 0;
27	MRSCont.flags.isHERCULES            = 0;
28	MRSCont.flags.isPRIAM               = 0;
29	MRSCont.flags.isMRSI                = 0;
30	MRSCont.flags.isSPECIAL             = 0;
31	MRSCont.flags.isSERIES              = 0;
32	MRSCont.flags.addImages             = 0;
33	MRSCont.flags.reordered             = 0;
34	MRSCont.opts.savePDF                = 0;
35	MRSCont.opts.saveLCM                = 0;
36	MRSCont.opts.savejMRUI              = 0;
37	MRSCont.opts.saveNII                = 1;
38	MRSCont.opts.saveVendor             = 0;
39	MRSCont.opts.fit.includeMetabs      = {'default'};      % Options: 'default', 'full', custom set
40	MRSCont.opts.fit.method             = 'Osprey';         % Options: 'Osprey' (default), 'LCModel'
41	MRSCont.opts.fit.range              = [0.2 4.2];        % Default: [0.2 4.2]
42	MRSCont.opts.fit.rangeWater         = [2.0 7.4];        % Default: [2.0 7.4]
43	MRSCont.opts.fit.style              = 'Separate';       % Options: 'Separate' (Default - will fit DIFF and OFF separately), 'Concatenated' (will fit DIFF and SUM simultaneously),
44	MRSCont.opts.fit.bLineKnotSpace     = 0.4;              % Baseline spline knot spacing [ppm]. Default: 0.4.
45	MRSCont.opts.fit.fitMM              = 1;                % Add MM and lipid basis functions to basis set? Default: 1.
46	MRSCont.opts.fit.coMM3              = 'none';           % Add co-edited MM3 peak model for GABA editing? Default: none.
47	MRSCont.opts.fit.FWHMcoMM3          = 14;               % FWHM [Hz] of the co-edited peak Default: 14 Hz.
48	MRSCont.opts.ECC.raw                = 1;                % Do ECC for all metabolite spectra.
49	MRSCont.opts.ECC.mm                 = 1;                 % Do ECC for all metabolite-nulled spectra.
50	MRSCont.opts.cosmetics.LB           = 0;                % Do cosmetic LB
51	MRSCont.opts.cosmetics.Zoom         = 2.75;             % Do cosmetic Zoom
52	MRSCont.opts.img.deface             = 0;                % Deface data
53	MRSCont.opts.load.undoPhaseCycle    = 1;                % Undo phase cycle for nifti MRS
54	%%% 2. FIND AND SET PATHS %%%
55	% Osprey
56	[settingsFolder,~,~] = fileparts(which('OspreySettings.m'));
57	if isempty(settingsFolder)
58	     error('Osprey not found! Please install Osprey (https://github.com/schorschinho/osprey) and include it in your MATLAB path.');
59	else
60	    allFolders      = strsplit(settingsFolder, filesep);
61	    ospFolder       = strjoin(allFolders(1:end-1), filesep); % parent folder (= Osprey folder)
62	end
63	
64	% SPM
65	% Check if SPM12 is installed
66	spmversion = fileparts(which('spm'));
67	if isempty(spmversion)
68	    warning('SPM not found! Please install SPM12 (https://www.fil.ion.ucl.ac.uk/spm/software/spm12) and include it in your MATLAB path.');
69	elseif strcmpi(spmversion(end-3:end),'spm8')
70	    warning(['SPM8 detected, but only SPM12 is supported. ' ...
71	           'Please install SPM12 (https://www.fil.ion.ucl.ac.uk/spm/software/spm12) and include it in your MATLAB path.']);
72	end
73	
74	%%% 3. INITIALISE MRSCONT FIELDS AND FLAGS %%%
75	% Set default fields
76	MRSCont.ospFolder           = ospFolder;
77	MRSCont.files               = {};
78	MRSCont.files_mm            = {};
79	MRSCont.files_ref           = {};
80	MRSCont.files_w             = {};
81	MRSCont.files_mm_ref        = {};
82	MRSCont.flags.hasMM         = 0;
83	MRSCont.flags.hasRef        = 0;
84	MRSCont.flags.hasWater      = 0;
85	MRSCont.flags.hasMMRef      = 0;
86	% Set default flags
87	MRSCont.flags.didLCMWrite   = 0;
88	MRSCont.flags.didjMRUIWrite = 0;
89	MRSCont.flags.didVendorWrite= 0;
90	MRSCont.flags.didJob        = 0;
91	MRSCont.flags.didLoad   = 0;
92	MRSCont.flags.didProcess    = 0;
93	MRSCont.flags.didCoreg      = 0;
94	MRSCont.flags.didSeg        = 0;
95	MRSCont.flags.didFit        = 0;
96	MRSCont.flags.didQuantify   = 0;
97	MRSCont.flags.didOverview   = 0;
98	
99	if (ismcc || isdeployed)
100	    if ismac
101	        currentDir = ctfroot;
102	        [currentDir,~,~] = fileparts(currentDir);
103	         SepFileList =  split(currentDir, filesep);
104	        index = find(strcmp(SepFileList,'application'));
105	        if ~isempty(index)
106	            MRSCont.opts.fit.basissetFolder = fullfile(SepFileList{1:index},'basissets');
107	        else
108	            MRSCont.opts.fit.basissetFolder = [];
109	        end
110	    end
111	    if isunix
112	    	currentDir = pwd;
113	    	SepFileList =  split(currentDir, filesep);
114	        index = find(strcmp(SepFileList,'application'));
115	        if ~isempty(index)
116	            MRSCont.opts.fit.basissetFolder = fullfile(SepFileList{1:index},'basissets');
117	        else
118	            MRSCont.opts.fit.basissetFolder = [];
119	        end
120	    end
121	    if ispc
122	        [~, result] = system('path');
123	        currentDir = char(regexpi(result, 'Path=(.*?);', 'tokens', 'once'));
124	        SepFileList =  split(currentDir, filesep);
125	        MRSCont.opts.fit.basissetFolder =currentDir;
126	        index = find(strcmp(SepFileList,'application'));
127	        if ~isempty(index)
128	            MRSCont.opts.fit.basissetFolder = fullfile(SepFileList{1:index},'basissets');
129	        else
130	            MRSCont.opts.fit.basissetFolder = [];
131	        end
132	    end
133	    
134	else
135	    MRSCont.opts.fit.basissetFolder = [];
136	end
137	
138	
139	end
