153	                else
154	                    raw_ref.flags.averaged    = 1;
155	                    raw_ref.dims.averages     = 0;
156	                end
157	            
158	                raw_ref = op_combine_water_subspecs(raw_ref);                
159	            end
160	
161	%%           %%% 1E. GET SHORT-TE WATER DATA %%%
162	             % And do the processing
163	             if MRSCont.flags.hasWater
164	                w_ll = MRSCont.opts.MultipleSpectra.w(ll);
165	                raw_w                           = MRSCont.raw_w{w_ll,kk};                % Get the kk-th dataset
166	                
167	                % Combine SPECIAL sub-spectra
168	                if MRSCont.flags.isSPECIAL
169	                    raw_w = combine_special_subspecs(raw_w);
170	                end
171	                
172	                if raw_w.averages > 1 && raw_w.flags.averaged == 0
173	                    [raw_w,fs,phs]                 = op_alignAverages(raw_w, 1, 'n');
174	                    badAverages=find(abs(fs)>6);
175	                    goodAverages=find(abs(fs)<6); 
176	                    if ~isempty(badAverages)
177	                        fs(badAverages) =[];
178	                        phs(badAverages) =[];
179	                        raw_w.AveragesToKeep = goodAverages;
180	                        raw_w.fids=raw_w.fids(:,goodAverages,:,:);
181	                        raw_w.specs=fftshift(ifft(raw_w.fids,[],raw_w.dims.t),raw_w.dims.t);
182	                        raw_w.sz=size(raw_w.fids);
183	                        raw_w.averages=length(goodAverages);
184	                    end
185	                    raw_w                       = op_averaging(raw_w);              % Average
186	                    raw_w.specReg{1}.fs              = fs; % save align parameters
187	                    raw_w.specReg{1}.phs             = phs; % save align parameters
188	                else
189	                    raw_w.flags.averaged    = 1;
190	                    raw_w.dims.averages     = 0;
191	                end
192	
193	                if raw_w.subspecs > 1
194	                    raw_w = op_combine_water_subspecs(raw_w);
