216	    %                 raw.specs = fftshift(fft(raw.fids,[],1));
217	    %             end
218	
219	                % Next, shift the entire metabolite spectrum by 0.15 ppm.
220	                % This doesn't have to be completely accurate, since additional

1	% op_alignScans.m
2	% Jamie Near, McGill University 2014.
3	% 
4	% USAGE:
5	% [out,ph,frq]=op_alignScans(in,in1,tmax,mode);
6	% 
7	% DESCRIPTION:
8	% Use spectral registration to align two separate scans (align in to in1);
9	% 
10	% INPUTS:
11	% in        = input (spectrum to be registered)
12	% in1       = base (spectrum that the input is to be registered to).
13	% tmax      = Maximum time (s) in time domain to use for registration.
14	% mode      = (optional)'f' - Frequency align only
15	%                  'p' - Phase align only
16	%                  'fp or pf' - Frequency and phase align (default)
17	%
18	% OUTPUTS:
19	% out       = Output following alignment of input (in) to the base spectrum.  
20	% ph        = Phase shift (in degrees) used for alignment.
21	% frq       = Frequency shift (in Hz) used for alignment.
22	
23	
24	function [out,ph,frq]=op_alignScans(in,in1,tmax,mode);
25	
26	
27	if ~in1.flags.addedrcvrs || ~in.flags.addedrcvrs
28	    error('ERROR:  I think it only makes sense to do this after you have combined the channels using op_addrcvrs.  ABORTING!!');
29	end
30	
31	if ~in1.flags.averaged || ~in.flags.averaged
32	    error('ERROR:  I think it only makes sense to do this after you have combined the averages using op_averaging.  ABORTING!!');
33	end
34	
35	% if in1.flags.isFourSteps || in.flags.isFourSteps
36	%     error('ERROR:  I think it only makes sense to do this after you have performed op_ISIScombine.  ABORTING!!');
37	% end
38	
39	% if ~in1.flags.subtracted  || ~in.flags.subtracted
40	%     error('ERROR:  I think it only makes sense to do this after you have combined the subspectra using op_combinesubspecs.  ABORTING!!');
41	% end
42	
43	if nargin<4
44	    mode='fp';
45	end
46	
47	switch mode
48	    case 'f'
49	        parsFit=0;
50	    case 'p'
51	        parsFit=0;
52	    case 'fp'
53	        parsFit=[0 0];
54	    case 'pf'
55	        mode='fp'
56	        parsFit=[0 0];
57	    otherwise
58	        error('ERROR:mode unrecognized.  Use "1" or "2".  ABORTING!');
59	end
60	
61	
62	base=in1;
63	base=[real(base.fids( in1.t>=0 & in1.t<tmax ));imag(base.fids( in1.t>=0 & in1.t<tmax))];
64	
65	%plot(in1.t,in1.fids,in.t,in.fids);
66	
67	parsGuess=parsFit;
68	%disp(['fitting subspec number ' num2str(m) ' and average number ' num2str(n)]);
69	switch mode
70	    case 'f'
71	        parsFit=nlinfit(in.fids(in.t>=0 & in.t<tmax),base,@op_freqShiftComplexNest,parsGuess);
72	        fids=op_freqShiftNest(parsFit,in.fids);
73	        frq=parsFit(1);
74	        ph=0;
75	    case 'p'
76	        parsFit=nlinfit(in.fids(in.t>=0 & in.t<tmax),base,@op_phaseShiftComplexNest,parsGuess);
77	        fids=op_phaseShiftNest(parsFit,in.fids);
78	        frq=0;
79	        ph=parsFit(1);
80	    case 'fp'
81	        parsFit=nlinfit(in.fids(in.t>=0 & in.t<tmax),base,@op_freqPhaseShiftComplexNest,parsGuess);
82	        fids=op_freqPhaseShiftNest(parsFit,in.fids);
83	        ph=parsFit(2);
84	        frq=parsFit(1);
85	end
86	
87	%figure
88	%plot(in1.t,in1.fids,in.t,fids);
89	
90	
91	%re-calculate Specs using fft
92	specs=fftshift(fft(fids,[],in.dims.t),in.dims.t);
93	
94	%plot(in1.ppm,combinedSpecs);
95	
96	%FILLING IN DATA STRUCTURES
97	out=in;
98	out.fids=fids;
99	out.specs=specs;
100	
101	%FILLING IN THE FLAGS
102	out.flags=in1.flags;
103	
