105	    function y=op_freqPhaseShiftComplexNest(pars,input);
106	        f=pars(1);     %Frequency Shift [Hz]
107	        p=pars(2);     %Phase Shift [deg]
108	        
109	        
110	        dwelltime=in.dwelltime;
111	        t=[0:dwelltime:(length(input)-1)*dwelltime];
112	        fid=input(:);
113	        
114	        shifted=addphase(fid.*exp(-1i*t'*f*2*pi),p);
115	        
116	        y=[real(shifted);imag(shifted)];
117	        %y=real(fid.*exp(-1i*t'*f*2*pi));
118	        
119	    end
120	
121	    function y=op_freqPhaseShiftNest(pars,input);
122	        f=pars(1);     %Frequency Shift [Hz]
123	        p=pars(2);     %Phase Shift [deg]
124	        
125	        
126	        dwelltime=in.dwelltime;
127	        t=[0:dwelltime:(length(input)-1)*dwelltime];
128	        fid=input(:);
129	        
130	        y=addphase(fid.*exp(-1i*t'*f*2*pi),p);
131	        %y=real(fid.*exp(-1i*t'*f*2*pi));
132	    end
133	
134	    function y=op_freqShiftComplexNest(pars,input);
135	        f=pars(1);     %Frequency Shift [Hz]
136	                
137	        dwelltime=in.dwelltime;
138	        t=[0:dwelltime:(length(input)-1)*dwelltime];
139	        fid=input(:);
140	        
141	        shifted=fid.*exp(-1i*t'*f*2*pi);
142	        
143	        y=[real(shifted);imag(shifted)];
144	        %y=real(fid.*exp(-1i*t'*f*2*pi));
145	        
146	    end
147	
148	    function y=op_freqShiftNest(pars,input);
149	        f=pars(1);     %Frequency Shift [Hz]
150	               
151	        dwelltime=in.dwelltime;
152	        t=[0:dwelltime:(length(input)-1)*dwelltime];
153	        fid=input(:);
154	        
155	        y=fid.*exp(-1i*t'*f*2*pi);
156	        %y=real(fid.*exp(-1i*t'*f*2*pi));
157	    end
158	    function y=op_phaseShiftComplexNest(pars,input);
159	        p=pars(1);     %Phase Shift [deg]
160	        
161	        
162	        dwelltime=in.dwelltime;
163	        t=[0:dwelltime:(length(input)-1)*dwelltime];
164	        fid=input(:);
165	        
166	        shifted=addphase(fid,p);
167	        
168	        y=[real(shifted);imag(shifted)];
169	        %y=real(fid.*exp(-1i*t'*f*2*pi));
170	        
171	    end
172	
173	    function y=op_phaseShiftNest(pars,input);
174	        p=pars(1);     %Phase Shift [deg]
175	        
176	        
177	        dwelltime=in.dwelltime;
178	        t=[0:dwelltime:(length(input)-1)*dwelltime];
179	        fid=input(:);
180	        
181	        y=addphase(fid,p);
182	        %y=real(fid.*exp(-1i*t'*f*2*pi));
183	    end
184	    
185	end
