1	% op_averaging.m
2	% Jamie Near, McGill University 2014.
3	% 
4	% USAGE:
5	% out=op_averaging(in);
6	% 
7	% DESCRIPTION:
8	% Combine the averages in a scan by adding the averages together and then 
9	% dividing by the number of averages.
10	% 
11	% INPUTS:
12	% in	= input data in matlab structure format.
13	%
14	% OUTPUTS:
15	% out   = Output following averaging.  
16	
17	function out=op_averaging(in);
18	
19	if in.flags.averaged
20	    error('ERROR:  Averaging has already been performed!  Aborting!');
21	end
22	
23	if in.dims.averages==0 || in.averages<2 || (length(in.sz)< in.dims.averages)
24	    %DO NOTHING
25	    warning('Just one average found. Returning input without modification!');
26	    %change the dims variables.
27	    dims.t=in.dims.t;
28	    if in.dims.coils>in.dims.averages
29	        dims.coils=in.dims.coils-1;
30	    else
31	        dims.coils=in.dims.coils;
32	    end
33	    dims.averages=0;
34	    if in.dims.subSpecs>in.dims.averages
35	        dims.subSpecs=in.dims.subSpecs-1;
36	    else
37	        dims.subSpecs=in.dims.subSpecs;
38	    end
39	    if in.dims.extras>in.dims.averages
40	        dims.extras=in.dims.extras-1;
41	    else
42	        dims.extras=in.dims.extras;
43	    end
44	    out=in;
45	    out.dims=dims;
46	    out.flags.averaged=1;
47	else
48	    
49	    %add the spectrum along the averages dimension;
50	    fids=sum(in.fids,in.dims.averages);
51	    fids=squeeze(fids);
52	    fids=fids/in.sz(in.dims.averages); %divide by number of averages;
53	    
54	    %re-calculate Specs using fft
55	    specs=fftshift(fft(fids,[],in.dims.t),in.dims.t);
56	    
57	    %change the dims variables.
58	    if in.dims.t>in.dims.averages
59	        dims.t=in.dims.t-1;
60	    else
61	        dims.t=in.dims.t;
62	    end
63	    if in.dims.coils>in.dims.averages
64	        dims.coils=in.dims.coils-1;
65	    else
66	        dims.coils=in.dims.coils;
67	    end
68	    dims.averages=0;
69	    if in.dims.subSpecs>in.dims.averages
70	        dims.subSpecs=in.dims.subSpecs-1;
71	    else
72	        dims.subSpecs=in.dims.subSpecs;
73	    end
74	    if in.dims.extras>in.dims.averages
75	        dims.extras=in.dims.extras-1;
76	    else
77	        dims.extras=in.dims.extras;
78	    end
79	    
80	    
81	    %re-calculate the sz variable
82	    sz=size(fids);
83	    
84	    % Add NIfTI-MRS provenance
85	    % Generate fields for provenance
86	    fields.Method   = 'Signal averaging';
87	    fields.Details  = ['Classic signal averaging, dim = DIM_DYN'];
88	    in = op_add_analysis_provenance(in,fields);
89	    
90	    %FILLING IN DATA STRUCTURE
91	    out=in;
92	    out.fids=fids;
93	    out.specs=specs;
94	    out.sz=sz;
95	    out.dims=dims;
96	    out.averages=1;
97	    
98	    %FILLING IN THE FLAGS
99	    out.flags=in.flags;
100	    out.flags.writtentostruct=1;
101	    out.flags.averaged=1;
102	
103	end
