1	%io_loadspec_rda.m
2	%
3	%Jay Hennessy, McGill University 2016.
4	%Heiner N. Raum, UKM Muenster 2024 (adaption of geometry header fields from XA30 to VE).
5	%
6	% USAGE:
7	% [out]=io_loadspec_rda(rda_filename);
8	%
9	% DESCRIPTION:
10	% Reads in siemens rda data (.rda file).
11	%
12	% op_loadspec_rda outputs the data in structure format, with fields corresponding to time
13	% scale, fids, frequency scale, spectra, and header fields containing
14	% information about the acquisition.  The resulting matlab structure can be
15	% operated on by the other functions in this MRS toolbox.
16	%
17	% INPUTS:
18	% pathname   = pathname of Siemens rda data to load. Can be folder or file,
19	% which will autmatically be distinguished.
20	%
21	% OUTPUTS:
22	% out        = Input dataset in FID-A structure format.
23	
24	function [out] = io_loadspec_rda(pathname)
25	
26	    if isfile(pathname)
27	        filesInFolder{1} = pathname;
28	    else
29	        % Create list of complete filenames (incl. path) in the folder
30	        dirFolder = dir(pathname);
31	        filesInFolder = dirFolder(~[dirFolder.isdir]);
32	        filesInFolder = filesInFolder(~ismember({filesInFolder.name}, {'.','..','.DS_Store'}));
33	        %hidden = logical(ones(1,length(filesInFolder)));
