1	function [refShift, refFWHM] = osp_XReferencing(dataToFit,frequencies,polarity,lim,realpart)
2	%% [refShift, refFWHM] = osp_XReferencing(dataToFit)
3	%   Calculates the reference shift and full-width half-maximum (FWHM) of a
4	%   spectrum according to the LCModel algorithm. The algorithm is described in:
5	%       S.W. Provencher, "Estimation of metabolite concentrations from
6	%       localized in vivo NMR spectra", Magn Reson Med 30(6):672-679 (1993)
7	%
8	%   The algorithm first determines the power spectrum of the input
9	%   spectrum, before calculating the cross-correlation with a function
10	%   containing delta functions at 2.01 ppm (NAA), 3.03 ppm (Cr), and 3.22
11	%   ppm (Cho).
12	%   The frequency of the largest peak of the cross-correlation function is
13	%   returned as the initial referencing shift of the input spectrum.
14	%   The FWHM of the largest peak of the cross-correlation function is 
15	%   returned as an estimate of the FWHM of the input spectrum.
16	%
17	%   Input:
18	%       dataToFit   = FID-A data structure
19	%
20	%   Output:
21	%       refShift    = Reference frequency shift (in Hz)
22	%       FWHM        = full-width half-maximum of the input spectrum (in ppm)
23	%
24	%   Author:
25	%       Dr. Georg Oeltzschner (Johns Hopkins University, 2018-10-12)
26	%       goeltzs1@jhmi.edu
27	%
28	%   History:
29	%       2018-10-12: First version of the code.
30	%
31	
32	if nargin < 5
33	    realpart = 0;
34	end
35	% We want to be able to process spectra that are not averaged and do have
36	% more then one sub-spectrum.
37	if dataToFit.dims.averages>0
38	    dataToFit = op_averaging(dataToFit);
39	end
40	
41	if dataToFit.dims.subSpecs>0
42	    ind = find(strcmp(dataToFit.names,'sum'));
43	    dataToFit = op_takesubspec(dataToFit,ind);       
44	end
45	
46	% Calculate power spectrum to estimate reference shift and FWHM
47	LimL = lim(1);
48	LimR = lim(2);
49	
50	if sum(frequencies<LimL) > 0
51	    LimL = min(frequencies);
52	end
53	
54	if sum(frequencies>LimR) > 0
55	    LimR = max(frequencies);
56	end
57	
58	dataToFit=op_freqrange(dataToFit,LimL,LimR);
59	spec = dataToFit.specs;
60	ppm  = dataToFit.ppm;
61	if ~realpart
62	    corrspec = spec .* conj(spec) / length(spec);
63	else
64	    corrspec = real(spec);
65	end
66	x = ppm;
67	y = zeros(size(x));
68	
69	% Set up delta functions
70	for Xc = 1 : length(frequencies)
71	[~,pos] = min((abs(x-frequencies(Xc))));
72	y(pos) = polarity(Xc);
73	end
74	
75	% Plot cross-correlation function, normalize it to its maximum
76	r = crosscorr(corrspec,y)';
77	r = r./(max(r));
78	% Set up Lorentzian fit to the central peak of the cross-correlation
79	% function
80	% x-axis of cross-correlation function
81	newx = [1:1:(2*length(spec)-1)];
82	
83	% fit the center peak
84	limits      = newx >= 0.94*length(spec) & newx <= 1.06*length(spec);
85	[max_value,max_ind] = max(r(limits));
86	tempx = newx(limits);
87	tempr = r(limits);
88	gtHalfMax=find(tempr >= 0.5 * max_value);
89	HWHM=abs(tempx(gtHalfMax(1)) - tempx(gtHalfMax(end)))/2 * 0.8;
90	if HWHM == 0
91	    gtHalfMax=find(tempr >= 0.3 * max_value);
92	    HWHM=abs(tempx(gtHalfMax(1)) - tempx(gtHalfMax(end)))/2 * 0.8;
93	end
94	
95	nlinopts    = statset('nlinfit');
96	% nlinopts    = statset(nlinopts,'MaxIter',1e8,'MaxFunEvals',1e8,'TolX',1e-10,'TolFun',1e-10);
97	LorentzModelInit = [1 HWHM tempx(max_ind) 0];
98	
99	try
100	    LorentzModelParam = lsqcurvefit(@LorentzModel,LorentzModelInit,newx(limits),real(r(limits)),[1 0 tempx(1) -180],[1 2*HWHM tempx(end) 180],nlinopts);
101	    % Return FWHM and reference shift
102	    refFWHM     = 2 * LorentzModelParam(2) * abs(ppm(1)-ppm(2));
103	    refShift    = (LorentzModelParam(3) - length(newx)/2) * (ppm(1)-ppm(2)) * dataToFit.txfrq*1e-6;
104	catch
105	    refFWHM     = nan;
106	    refShift    = 0;
107	end
108	
109	%%% embedded Lorentzian model function
110	function Lorentz = LorentzModel(x,freq)
111	% CJE LorentzModel
112	% Lorentzian  = (1/pi) * (hwhm) / (deltaf^2 + hwhm^2) (Wolfram)
113	% Peak height of Lorentzian = 4 / (pi*hwhm)
114	% This defnition of the Lorentzian has Area = 1
115	
116	area = x(1);
117	hwhm = x(2);
118	f0 = x(3);
119	phase = x(4);
120	
121	Absorption = 1/(2*pi) * area * ones(size(freq)) .* hwhm ./ ((freq-f0).^2 + hwhm.^2);
122	Dispersion = 1/(2*pi) * area * (freq-f0) ./ ((freq-f0).^2 + hwhm.^2);
123	
124	Lorentz = Absorption*cos(phase) + Dispersion * sin(phase);
125	end
126	
127	end
128

1	% op_freqrange.m
2	% Jamie Near, McGill University 2014.
3	% 
4	% USAGE:
5	% out=op_freqrange(in,ppmmin,ppmmax);
6	% 
7	% DESCRIPTION:
8	% Output only a specified frequency range of the input spectrum.
9	% 
10	% INPUTS:
11	% in         = input data in matlab structure format.
12	% ppmmin     = minimum extent of frequency range in ppm.
13	% ppmmax     = maximum extent of frequency range in ppm.
14	%
15	% OUTPUTS:
16	% out        = Output following frequency range selection.
17	
18	function out=op_freqrange(in,ppmmin,ppmmax,npoints);
19	if nargin < 4
20	    npoints = 0;
21	end
22	%Calculate Specs using fft
23	fullspecs=fftshift(fft(in.fids,[],in.dims.t),in.dims.t);
24	
25	%now take only the specified range of the spectrum
26	specs=fullspecs(in.ppm>=ppmmin & in.ppm<=ppmmax,:,:,:,:);
27	
28	if npoints ~= 0 && npoints > length(specs)
29	    specs=fullspecs(:,:,:,:,:);
30	    ppm = in.ppm;
31	
32	else if npoints ~= 0 && npoints < length(specs)
33	    ppmmin = ppmmin + (in.ppm(2) -in.ppm(1));
34	    specs=fullspecs(in.ppm>=ppmmin & in.ppm<=ppmmax,:,:,:,:);
35	    %calculate the ppm scale
36	    ppm=in.ppm(in.ppm>=ppmmin & in.ppm<=ppmmax);
37	else
38	    %calculate the ppm scale
39	    ppm=in.ppm(in.ppm>=ppmmin & in.ppm<=ppmmax);
40	    end
41	end
42	
43	
44	
45	
46	%convert back to time domain
47	%if the length of Fids is odd, then you have to do a circshift of one to
48	%make sure that you don't introduce a small frequency shift into the fids
49	%vector.
50	if mod(size(specs,in.dims.t),2)==0
51	    %disp('Length of vector is even.  Doing normal conversion');
52	    fids=ifft(fftshift(specs,in.dims.t),[],in.dims.t);
53	else
54	    %disp('Length of vector is odd.  Doing circshift by 1');
55	    fids=ifft(circshift(fftshift(specs,in.dims.t),1),[],in.dims.t);
56	end
57	
58	%calculate the size;
59	sz=size(fids);
60	
61	
62	%calculate the new spectral width and dwelltime:
63	dppm=abs(ppm(2)-ppm(1));
64	ppmrange=abs((ppm(end)-ppm(1)))+dppm;
65	spectralwidth=ppmrange*in.Bo*42.577;
66	dwelltime=1/spectralwidth;
67	
68	%calculate the time scale
69	t=[0:dwelltime:(sz(1)-1)*dwelltime];
70	
71	
72	
73	%FILLING IN DATA STRUCTURE
74	out=in;
75	out.fids=fids;
76	out.specs=specs;
77	out.sz=sz;
78	out.ppm=ppm;  
79	out.t=t; 
80	out.spectralwidth=spectralwidth;
81	out.dwelltime=dwelltime;
82	
83	%FILLING IN THE FLAGS
84	out.flags=in.flags;
85	out.flags.writtentostruct=1;
86	out.flags.freqranged=1;

