function out = osp_polarityToPositiveCr(in)

% Make the polarity of the common creatine-like reference component
% upright. This is intentionally idempotent: already polarity-consistent
% subspectra are returned unchanged.

out = in;
if ~isfield(in,'ppm') || ~isfield(in,'specs')
    return;
end
refMask = in.ppm >= 2.8 & in.ppm <= 3.2;
if ~any(refMask)
    return;
end
refSpec = real(in.specs(refMask,:,:,:,:));
if isempty(refSpec)
    return;
end
polarity = abs(max(refSpec(:))) - abs(min(refSpec(:)));
if polarity < 0
    out = op_ampScale(in,-1);
end

end
